const http = this.helpers.httpRequest;

// ⚙️ CONFIG
async function sendMsg(phone, text) {
  return http({
    method: 'POST',
    url: 'http://148.230.90.171:8096/message/sendText/wasapea-7c7a2c6c',
    headers: { 'apikey': 'wasapea-evo-key-2026', 'Content-Type': 'application/json' },
    body: { number: phone, text: text }
  });
}


// 📱 SUBSCRIBERS — plan 'pro' gets monitor alerts
const subscribers = [
  { phone: '573106055920', plan: 'free' },
  // { phone: '573001234567', plan: 'pro' },
];


// 1. Parse webhook payload from Uptime Kuma
const payload = $input.first().json;
const name = payload.monitor?.name || payload.msg || 'Unknown';
const status = payload.heartbeat?.status === 0 ? '🔴 CAÍDO' : '🟢 RECUPERADO';
const url = payload.monitor?.url || '';

const text = '🛡️ *MonitorPro Alerta*\n\n' +
  '*' + name + '* está ' + status + '\n' +
  '🔗 ' + url + '\n' +
  '🕐 ' + new Date().toLocaleString('es-CO', { timeZone: 'America/Bogota' }) + '\n\n' +
  '⚡ *Vigilante Digital*';

// 2. Send to pro subscribers
const results = [];
for (const sub of subscribers) {
  try {
    await sendMsg(sub.phone, text);
    results.push({ phone: sub.phone, status: 'sent' });
  } catch (e) {
    results.push({ phone: sub.phone, status: 'error', error: e.message });
  }
}

return { alert: name, status: status, sent: results.length, results };
